"""Real JEE Main questions — Chemistry Unit 19: Biomolecules (carbohydrates, proteins, enzymes, vitamins, nucleic acids).
Our own solutions; chk recomputes counts (peptide sequences, H-bonds, complementary strands, carbon/iodine content)
by code and checks fact items against data tables written from NCERT (essential amino acids, vitamin solubility,
glycosidic links, hydrolysis products, reactions of glucose)."""
import re
from math import factorial
from common import new_registry, pick, verify
from chemkit import stmt, pickset
P, add = new_registry()
AM = {'C': 12, 'H': 1, 'N': 14, 'O': 16, 'S': 32, 'I': 127}
def mm(f): return sum(AM[e] * (int(n) if n else 1) for e, n in re.findall(r'([A-Z][a-z]?)(\d*)', f))
def atoms(f, el): return sum(int(n) if n else 1 for e, n in re.findall(r'([A-Z][a-z]?)(\d*)', f) if e == el)
PAIR = {'A': 'T', 'T': 'A', 'G': 'C', 'C': 'G'}
HB = {'A': 2, 'T': 2, 'G': 3, 'C': 3}
def comp(s): return ''.join(PAIR[b] for b in s)
ESS = {'valine', 'leucine', 'isoleucine', 'phenylalanine', 'tryptophan', 'threonine', 'methionine', 'lysine', 'arginine', 'histidine'}
FAT = {'A', 'D', 'E', 'K'}
VNAME = {'B1': 'thiamine', 'B2': 'riboflavin', 'B6': 'pyridoxine', 'C': 'ascorbic acid', 'B12': 'cyanocobalamin'}
LINK = {'sucrose': 'α1–β2', 'maltose': 'α1–4', 'lactose': 'β1–4', 'amylose': 'α1–4', 'amylopectin': 'α1–4 and α1–6', 'cellulose': 'β1–4', 'glycogen': 'α1–4 and α1–6'}
GLU_RX = {'hydroxylamine': 'glucoxime', 'Br2 water': 'gluconic acid', 'excess acetic anhydride': 'glucose pentaacetate', 'conc. HNO3': 'saccharic acid', 'HI, heat': 'n-hexane', 'NaHCO3': 'no reaction'}
STO = ['Both Statement I and Statement II are false', 'Statement I is true but Statement II is false', 'Both Statement I and Statement II are true', 'Statement I is false but Statement II is true']
def rom(seq, opts): return pick([o.replace(' ', '') for o in opts], seq.replace(' ', ''))

